import { NextRequest, NextResponse } from "next/server";
import { auth } from "../../../../../../../auth";
import db from "@/lib/prisma";
import { z } from "zod";
import { BIBBLE_HISTORY_MESSAGE_MAX_CHARS } from "@/lib/bibble/attachment-security";

export const dynamic = "force-dynamic";

const turnSchema = z.object({
  userContent: z.string().trim().min(1).max(BIBBLE_HISTORY_MESSAGE_MAX_CHARS),
  assistantContent: z.string().trim().min(1).max(1_000_000),
  assistantTokens: z.number().int().positive().max(1_000_000).optional(),
  tokenCountExact: z.literal(true).optional(),
}).strict();

export async function POST(
  req: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  const session = await auth();
  if (!session?.user?.id) return NextResponse.json({ error: "Unauthorized" }, { status: 401 });

  const userId = Number(session.user.id);
  const { id } = await params;

  const owned = await db.bibbleSession.findFirst({ where: { id, userId } });
  if (!owned) return NextResponse.json({ error: "Not found" }, { status: 404 });

  const parsed = turnSchema.safeParse(await req.json().catch(() => null));
  if (!parsed.success) return NextResponse.json({ error: "Turno inválido" }, { status: 400 });
  const { userContent, assistantContent, assistantTokens, tokenCountExact } = parsed.data;

  try {
    await db.$transaction([
      db.bibbleMessage.create({ data: { sessionId: id, role: "user", content: userContent } }),
      db.bibbleMessage.create({ data: { sessionId: id, role: "assistant", content: assistantContent, tokens: tokenCountExact ? assistantTokens : null } }),
      db.bibbleSession.update({ where: { id }, data: { updatedAt: new Date() } }),
    ]);
  } catch (err) {
    console.error("[bibble/messages] transaction-failed", { error: err instanceof Error ? err.name : "unknown" });
    return NextResponse.json({ error: "Failed to save messages" }, { status: 500 });
  }

  return new NextResponse(null, { status: 204 });
}
